/**
 * @summary Serve a stored object
 */
export const getGetStorageObjectUrl = (
  objectPath: string,
  params?: GetStorageObjectParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/storage/objects/${objectPath}?${stringifiedParams}`
    : `/api/storage/objects/${objectPath}`;
};

export const getStorageObject = async (
  objectPath: string,
  params?: GetStorageObjectParams,
  options?: RequestInit,
): Promise<Blob> => {
  return customFetch<Blob>(getGetStorageObjectUrl(objectPath, params), {
    ...options,
    method: "GET",
  });
};

export const getGetStorageObjectQueryKey = (
  objectPath: string,
  params?: GetStorageObjectParams,
) => {
  return [
    `/api/storage/objects/${objectPath}`,
    ...(params ? [params] : []),
  ] as const;
};

